// ParentRetrievalHooks declares complete-model read callbacks. Reference a local factory with retrieval=Factory on the model directive. The stored model is a read-only value; getters remain explicit.
type ParentRetrievalHooks struct {
	// Retrieved runs after successful stored hydration and row closure. The executor retains the caller's capability and wrappers; no write transaction is created implicitly. Return an error to stop this read. Nil is skipped.
	Retrieved func(context.Context, database.Executor, Parent) error
}

// ParentRetrievalObserver retains this model's concrete retrieval factory type. Names share the selected database's write/retrieval namespace.
type ParentRetrievalObserver = lifecycle.Observer[Parent, ParentRetrievalHooks]

// NewParentRetrievalObserver declares a typed retrieval observer without registering or constructing hooks.
func NewParentRetrievalObserver(observer string) ParentRetrievalObserver {
	return lifecycle.NewRetrievalObserver[Parent, ParentRetrievalHooks](observer)
}

// RegisterParentRetrievalObserver binds dependency construction to a database module. Its factory runs once per nonempty complete fetch/batch and selected model role; write hydration, DTOs and scalar reads skip it.
func RegisterParentRetrievalObserver(registrar *foundation.Registrar, pool foundation.Key[*database.DB], observer ParentRetrievalObserver, construct func(foundation.Resolver) (func() ParentRetrievalHooks, error)) error {
	return database.RegisterObserver(registrar, pool, observer, construct)
}
func (ParentRetrievalHooks) foundryRetrievalHooks(ctx context.Context, observerSet lifecycle.Observers) (foundryquery.RetrievalHooks[Parent], error) {
	factories, err := lifecycle.RetrievalObserverFactories[Parent, ParentRetrievalHooks](observerSet)
	if err != nil {
		return foundryquery.RetrievalHooks[Parent]{}, err
	}
	var allHooks []ParentRetrievalHooks
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Parent]{}, err
	}
	for _, factory := range factories {
		if err := ctx.Err(); err != nil {
			return foundryquery.RetrievalHooks[Parent]{}, err
		}
		allHooks = append(allHooks, factory())
	}
	if err := ctx.Err(); err != nil {
		return foundryquery.RetrievalHooks[Parent]{}, err
	}
	return foundryquery.RetrievalHooks[Parent]{Retrieved: func(ctx context.Context, executor database.Executor, item Parent) error {
		for _, hooks := range allHooks {
			if err := ctx.Err(); err != nil {
				return err
			}
			if hooks.Retrieved != nil {
				if err := hooks.Retrieved(ctx, executor, item); err != nil {
					return err
				}
			}
		}
		return ctx.Err()
	}}, nil
}

// ParentAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type ParentAuditPolicy struct {
	_ [0]*Parent
	// ID controls the audit representation of stored joined_parents.id.
	ID record.Disclosure
	// Name controls the audit representation of stored joined_parents.name.
	Name record.Disclosure
	// DeletedAt controls the audit representation of stored joined_parents.deleted_at.
	DeletedAt record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes ParentChanges) Audit(policy ParentAuditPolicy) (record.Model[Parent, int64], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Parent, int64]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Parent, int64]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Parent, int64]{}, err
	}
	if err = record.Capture(builder, "id", codec.Signed[int64](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Parent, int64]{}, err
	}
	if err = record.Capture(builder, "name", codec.String[string](), changes.fields.Name, policy.Name); err != nil {
		return record.Model[Parent, int64]{}, err
	}
	if err = record.Capture(builder, "deleted_at", codec.Nullable(codec.DateTime()), changes.fields.DeletedAt, policy.DeletedAt); err != nil {
		return record.Model[Parent, int64]{}, err
	}
	return builder.Build()
}

// ParentAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type ParentAuditFieldSet struct {
	_ [0]*Parent
	// ID retains stored joined_parents.id after write mutators; read accessors do not replace audit values.
	ID foundryvalue.Optional[record.FieldChange[int64]]
	// Name retains stored joined_parents.name after write mutators; read accessors do not replace audit values.
	Name foundryvalue.Optional[record.FieldChange[string]]
	// DeletedAt retains stored joined_parents.deleted_at after write mutators; read accessors do not replace audit values.
	// Managed soft-delete timestamp: Delete sets this stored field and Restore clears it. Ordinary queries exclude deleted models; WithTrashed and OnlyTrashed select visibility explicitly. Assigning this field directly through a draft uses ordinary create/update hooks rather than deletion/restoration events.
	DeletedAt foundryvalue.Optional[record.FieldChange[foundryvalue.Nullable[temporal.DateTime]]]
}

// ParentAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func ParentAuditFields(history record.Model[Parent, int64]) (ParentAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return ParentAuditFieldSet{}, err
	}
	var fields ParentAuditFieldSet
	fields.ID, err = record.ReadField(view, "id", codec.Signed[int64]())
	if err != nil {
		return ParentAuditFieldSet{}, err
	}
	fields.Name, err = record.ReadField(view, "name", codec.String[string]())
	if err != nil {
		return ParentAuditFieldSet{}, err
	}
	fields.DeletedAt, err = record.ReadField(view, "deleted_at", codec.Nullable(codec.DateTime()))
	if err != nil {
		return ParentAuditFieldSet{}, err
	}
	return fields, nil
}

// ParentAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func ParentAuditing(policy ParentAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Parent]()
		if err != nil {
			return err
		}
		return RegisterParentObserver(registrar, pool, NewParentObserver(name), func(resolver foundation.Resolver) (func() ParentHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() ParentHooks {
				write := func(ctx context.Context, tx *database.Tx, changes ParentChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return ParentHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
